                  <div style={{padding:'0.75rem',background:'#ef444422',borderRadius:6}}><div style={{fontSize:'0.8rem',color:'#888'}}>Before</div><div style={{fontWeight:600}}>{cbResult.thought_record.emotion} {cbResult.thought_record.intensity_before}/10</div></div>
